@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class LogisticsClient {
    public static final BlockPos Q=new BlockPos(280,205,8);static int ticks,stage;static long due;static WorkerGolem g,other;static SealEntity source,dest;static ChestBlockEntity in,out;static ItemEntity drop;static LivingEntity victim;static int frozen;static boolean saturated;
    static int count(ChestBlockEntity c,Item item){return GolemClient.count(c,item);}
    static SealEntity chestSeal(ServerPlayer p,SealKind k,BlockPos at){var s=GolemClient.chestSeal(p,k,at);((ChestBlockEntity)p.level().getBlockEntity(s.support())).clearContent();return s;}
    static void remove(SealEntity s){GolemClient.remove(s);}
    static WorkerGolem spawn(ServerPlayer p,GolemDesign d,BlockPos pos){var before=p.level().getEntitiesOfClass(WorkerGolem.class,new AABB(pos).inflate(2)).stream().map(Entity::getUUID).collect(java.util.stream.Collectors.toSet());GolemClient.spawn(p,d,pos);return p.level().getEntitiesOfClass(WorkerGolem.class,new AABB(pos).inflate(1)).stream().filter(x->!before.contains(x.getUUID())).findFirst().orElseThrow();}
    static void reset(ServerPlayer p){var l=p.level();for(int x=16;x<=19;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var q:BlockPos.betweenClosed(Q.offset(-14,0,-10),Q.offset(22,6,10)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-14,-1,-10),Q.offset(22,-1,10)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());for(var e:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(40)))e.discard();for(var e:l.getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(40)))e.discard();}
    static void snapshot(ServerPlayer p){var o=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());g.saveWithoutId(o);var copy=new WorkerGolem(GolemContent.GOLEM.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),o.buildResult()));check(copy.delivery().equals(g.delivery())&&ItemStack.matches(copy.requested(),g.requested())&&ItemStack.matches(copy.cargo.getItem(0),g.cargo.getItem(0)),"Actual requested cargo snapshot lost route/items");g.discard();copy.setUUID(UUID.randomUUID());g=copy;check(p.level().addFreshEntity(g),"Cannot restore in-flight native worker");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("logistics-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
        if(stage==0){knowledge(p);p.setGameMode(GameType.SURVIVAL);reset(p);p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);source=GolemProbe.seal(p,SealKind.PICKUP_ADVANCED,Q.offset(4,0,2));source.sample(0,new ItemStack(Items.EMERALD));source.sample(8,LogisticsProbe.parcel(1));dest=chestSeal(p,SealKind.FILL_ADVANCED,Q.east(12));dest.sample(8,LogisticsProbe.parcel(1));out=(ChestBlockEntity)l.getBlockEntity(dest.support());drop=new ItemEntity(l,Q.getX()+4.5,Q.getY()+.1,Q.getZ()+.5,LogisticsProbe.parcel(21));l.addFreshEntity(drop);g=spawn(p,GolemDesign.BASIC,Q.east(2));stage=1;due=now+50;return;}
        if(stage==1&&now>=due){check(drop.isAlive()&&drop.getItem().getCount()==21&&g.cargo.isEmpty()&&count(out,Items.DIAMOND)==0,"Basic worker executed Smart seal");g.discard();g=spawn(p,new GolemDesign(3,1,0,3),Q.east(2));stage=2;due=now+350;return;}
        if(stage==2){check(now<due,"Advanced pickup/fill timed out "+g.position());if(count(out,Items.DIAMOND)!=21)return;check(!drop.isAlive()&&out.getItem(0).getHoverName().getString().equals("Requested parcel"),"Advanced filter lost physical component");remove(source);remove(dest);source=chestSeal(p,SealKind.EMPTY_ADVANCED,Q.west(7));source.sample(8,new ItemStack(Items.EMERALD));source.blacklist=true;source.exact=false;in=(ChestBlockEntity)l.getBlockEntity(source.support());in.setItem(0,new ItemStack(Items.EMERALD,9));in.setItem(1,LogisticsProbe.parcel(13));dest=chestSeal(p,SealKind.FILL_ADVANCED,Q.east(12));out=(ChestBlockEntity)l.getBlockEntity(dest.support());stage=3;due=now+500;Thaumcraft.LOGGER.info("LOGISTICS_ADVANCED_PICKUP_OK: Smart gate, ninth filter and named physical delivery");return;}
        if(stage==3){check(now<due,"Advanced empty/fill timed out");if(count(out,Items.DIAMOND)!=13)return;check(count(in,Items.EMERALD)==9&&count(out,Items.EMERALD)==0,"Advanced exclusion extracted excluded items");remove(source);remove(dest);g.discard();source=chestSeal(p,SealKind.PROVIDER,Q.west(7));in=(ChestBlockEntity)l.getBlockEntity(source.support());in.setItem(0,LogisticsProbe.parcel(64));dest=chestSeal(p,SealKind.STOCK,Q.east(16));dest.sample(8,LogisticsProbe.parcel(1));dest.amounts[8]=23;out=(ChestBlockEntity)l.getBlockEntity(dest.support());out.setItem(0,LogisticsProbe.parcel(7));g=spawn(p,GolemDesign.BASIC,Q.west(3));other=spawn(p,GolemDesign.BASIC,Q.west(2));check(g!=other&&!g.getUUID().equals(other.getUUID()),"Fixture must track two distinct deployed workers");source.channel=1;stage=4;due=now+50;Thaumcraft.LOGGER.info("LOGISTICS_ADVANCED_EMPTY_OK: ninth blacklist sample, exact components and sided physical transfer");return;}
        if(stage==4&&now>=due){check(count(in,Items.DIAMOND)==64&&count(out,Items.DIAMOND)==7,"Different-channel provider supplied a request");source.channel=0;stage=5;due=now+400;return;}
        if(stage==5){check(now<due,"Requested provider extraction timed out");if(g.delivery()==null&&other.delivery()==null)return;if(g.delivery()==null){var tmp=g;g=other;other=tmp;}check(count(in,Items.DIAMOND)==48&&g.cargo.getItem(0).getCount()==16,"Request did not fetch only actual deficit");snapshot(p);l.setBlockAndUpdate(dest.getBlockPos().south(),Blocks.REDSTONE_BLOCK.defaultBlockState());frozen=count(out,Items.DIAMOND);stage=6;due=now+50;return;}
        if(stage==6&&now>=due){check(count(out,Items.DIAMOND)==frozen&&g.cargo.getItem(0).getCount()==16&&count(in,Items.DIAMOND)==48,"Powered destination lost or delivered pending cargo");l.removeBlock(dest.getBlockPos().south(),false);stage=7;due=now+400;return;}
        if(stage==7){check(now<due,"Saved in-flight delivery did not resume "+g.position());if(count(out,Items.DIAMOND)!=23)return;check(count(in,Items.DIAMOND)==48&&g.cargo.isEmpty()&&other.cargo.isEmpty(),"Concurrent supply mismatch: source="+count(in,Items.DIAMOND)+" g="+g.cargo.getItem(0)+" other="+other.cargo.getItem(0)+" route="+g.delivery()+" otherRoute="+other.delivery());stage=8;due=now+80;Thaumcraft.LOGGER.info("LOGISTICS_PROVISION_OK: two workers, exact deficit, real two-leg travel, channel/redstone and in-flight snapshot recovery");return;}
        if(stage==8&&now>=due){check(count(out,Items.DIAMOND)==23&&count(in,Items.DIAMOND)==48,"Completed stock keeps extracting");dest.amounts[8]=40;stage=9;due=now+400;return;}
        if(stage==9){check(now<due,"Second stock request did not start");if(g.delivery()==null&&other.delivery()==null)return;if(g.delivery()==null){var tmp=g;g=other;other=tmp;}check(g.cargo.getItem(0).getCount()==17,"Second deficit not exact");out.setItem(0,LogisticsProbe.parcel(40));other.setMode(2);stage=10;due=now+180;return;}
        if(stage==10&&now>=due){check(count(out,Items.DIAMOND)==40&&g.cargo.getItem(0).getCount()==17&&count(in,Items.DIAMOND)==31,"External stock change overfilled or destroyed in-flight items");remove(source);remove(dest);g.dropCargo(l);g.discard();other.discard();source=GolemProbe.seal(p,SealKind.BREAKER_ADVANCED,Q.east(4).above());source.sample(8,new ItemStack(Items.STONE));source.silk=true;g=spawn(p,new GolemDesign(1,1,3,0),Q.east(2));stage=11;due=now+240;Thaumcraft.LOGGER.info("LOGISTICS_SURPLUS_OK: destination filled externally, 17 physical surplus items retained without overstock");return;}
        if(stage==11){check(now<due,"Advanced Silk breaker timed out");if(!l.isEmptyBlock(Q.east(4)))return;check(g.cargo.getItem(0).is(Items.STONE),"Silk breaker produced cobblestone");remove(source);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(1,1,0,2),Q.east(2));source=GolemProbe.seal(p,SealKind.GUARD_ADVANCED,Q.offset(4,0,2));source.guardMode=1;var cow=new net.minecraft.world.entity.animal.cow.Cow(net.minecraft.world.entity.EntityTypes.COW,l);cow.setPos(Vec3.atBottomCenterOf(Q.east(5)));cow.setNoAi(true);l.addFreshEntity(cow);victim=cow;stage=12;due=now+240;Thaumcraft.LOGGER.info("LOGISTICS_SILK_OK: Smart/Breaker gate and ninth-filter native Silk Touch loot");return;}
        if(stage==12){check(now<due,"Advanced animal guard timed out");if(victim.getHealth()>=victim.getMaxHealth())return;victim.discard();source.guardMode=2;var human=new ServerPlayer(e.server(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"LogisticsPVP"),ClientInformation.createDefault());boolean pvp=l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.PVP);l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,false,e.server());check(!GolemLogistics.guard(source,p,human)&&!GolemLogistics.guard(source,p,p),"Advanced guard bypasses PVP/owner protection");l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,pvp,e.server());human.getAbilities().instabuild=true;check(!GolemLogistics.guard(source,p,human),"Advanced guard targets creative players");remove(source);g.discard();source=chestSeal(p,SealKind.STOCK,Q.north(3));source.sample(8,LogisticsProbe.parcel(1));source.amounts[8]=23;p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);p.openMenu(source);stage=13;Thaumcraft.LOGGER.info("LOGISTICS_CLIENT_OK: seven new seals, Smart gates, advanced targets, exact stock/surplus, persistence and no duplication");}
    }
}
